var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddSingleton<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));
builder.Services.AddHttpClient("api")
    .ConfigureHttpMessageHandlerBuilder(b =>
    {
        ((HttpClientHandler)b.PrimaryHandler).UseCookies = false;
    });
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
});
var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

arguments.new_str:
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();
// CacheService is singleton but depends on scoped IUserService — use a factory that
// creates a scope, satisfying ValidateScopes (now enabled by default in development).
builder.Services.AddSingleton<ICacheService>(sp =>
{
    using var scope = sp.CreateScope();
    return new CacheService(scope.ServiceProvider.GetRequiredService<IUserService>());
});
// .NET 9: Default primary handler is SocketsHttpHandler; cast to HttpClientHandler throws.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { UseCookies = false });
// .NET 9: Header values in Trace-level HttpClientFactory logs are redacted by default.
// Allowlist non-sensitive headers needed for debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(name =>
        name != "X-Request-Id" && name != "X-Correlation-Id" && name != "Content-Type"));
// .NET 9: ForwardedHeadersMiddleware ignores X-Forwarded-* from unknown proxies.
// Configure KnownProxies/KnownNetworks for your reverse proxy.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    // Add the trusted reverse-proxy address(es):
    options.KnownProxies.Add(System.Net.IPAddress.Parse("127.0.0.1"));
});
var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

